let ctx;
let shapes = [];
let colors = ['#119da4', '#13505b', '#040404', '#e8f0ff', '#d00000', '#ffba08', '#083d77', '#da4167'];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	ctx = drawingContext;

	let columns = 20;
	let total = columns;
	let nums = [];
	while (total > 0) {
		let n = random([1, 2]);
		if (total - n < 0) {
			n = total;
		}
		total -= n;
		nums.push(n);
	}
	let minSize = width / columns;
	let x = 0;
	background('#e8f0ff');
	strokeWeight(width * 0.00);
	for (let i of nums) {
		let w = i * minSize;
		let y = height;
		let c = int((2 / (i)) * int(random(5, 10)));
		let type = 0;
		if (i == 2) {
			type = 1;
		}
		drawTower(x + w / 2, y - w / 2, w, c, type);
		x += w;
	}
}

