function drawTower(x, y, w, c, type) {
	while (c > 0) {
		if (type == 1 && random() < 0.5) {
			if (c == 1) {
				drawRoof(x + w / 4, y + w / 4, w / 2);
				drawRoof(x - w / 4, y + w / 4, w / 2);
			} else {
				drawWall(x + w / 4, y + w / 4, w / 2);
				drawWall(x - w / 4, y + w / 4, w / 2);
				drawWall(x + w / 4, y - w / 4, w / 2);
				drawWall(x - w / 4, y - w / 4, w / 2);
			}
		} else {
			if (c == 1) {
				drawRoof(x, y, w);
			} else {
				drawWall(x, y, w);
			}
		}
		c--;
		y -= w;
	}
}

function drawWall(x, y, w) {
	let type = int(random(15));
	let clr1 = random(colors);
	let clr2 = random(colors);
	while (clr1 == clr2) {
		clr1 = random(colors);
		clr2 = random(colors);
	}
	push();
	translate(x, y);
	fill(clr1);
	square(0, 0, w);
	fill(clr2);
	if (type == 0) {
		square(0, 0, w * 0.5);
		line(-w / 4, 0, w / 4, 0);
		line(0, w / 4, 0, -w / 4);
	} else if (type == 1) {
		beginShape();
		vertex(-w / 4, w / 2);
		for (let a = PI; a < TAU; a += TAU / 180) {
			vertex(w * 0.25 * cos(a), w * 0.25 * sin(a));
		}
		vertex(w / 4, w / 2);
		endShape(CLOSE);
	} else if (type == 2) {
		triangle(-w / 2, w / 2, w / 2, w / 2, 0, -w / 2);
	} else if (type == 3) {
		beginShape();
		vertex(-w / 2, -w / 2);
		vertex(-w / 2, w / 2);
		vertex(0, -w / 2);
		vertex(w / 2, w / 2);
		vertex(w / 2, -w / 2);
		vertex(0, w / 2);
		endShape(CLOSE);
	} else if (type == 4) {
		beginShape();
		vertex(-w / 2, -w / 2);
		vertex(w / 2, w / 2);
		vertex(w / 2, -w / 2);
		vertex(-w / 2, w / 2);
		endShape(CLOSE);
	} else if (type == 5) {
		rect(-w / 4, 0, w / 4, w / 2);
		rect(w / 4, 0, w / 4, w / 2);
	} else if (type == 6) {
		for (let i = 0; i < 4; i++) {
			arc(w * 0.02, w * 0.02, w * 0.5, w * 0.5, 0, PI / 2);
			rotate(PI / 2);
		}
	} else if (type == 7) {
		beginShape();
		vertex(w / 2, w / 2);
		vertex(-w / 2, w / 2);
		vertex(0, 0);
		endShape(CLOSE);
		beginShape();
		vertex(w / 2, 0);
		vertex(-w / 2, 0);
		vertex(0, -w / 2);
		endShape(CLOSE);
	} else if (type == 8) {
		for (let i = 0; i < 4; i++) {
			square(w * 0.2, w * 0.2, w * 0.25);
			rotate(PI / 2);
		}
	} else if (type == 9) {
		arc(0, 0, w * 0.8, w * 0.8, PI, TAU, PIE);
		square(0, w / 4, w * 0.25);
	} else if (type == 10) {
		beginShape();
		vertex(-w / 2, w / 4);
		vertex(w / 2, w / 4);
		vertex(w / 2, 0);
		vertex(w / 4, 0);
		vertex(w / 4, w / 2);
		vertex(0, w / 2);
		vertex(0, 0);
		vertex(-w / 4, 0);
		vertex(-w / 4, w / 2);
		vertex(-w / 2, w / 2);
		endShape();
	} else if (type == 11) {
		circle(w / 4, w / 4, w * 0.5);
		circle(-w / 4, -w / 4, w * 0.5);
		circle(-w / 4, w / 4, w * 0.2);
		circle(w / 4, -w / 4, w * 0.2);
	} else if (type == 12) {
		rect(-w * 0.2, w / 4, w * 0.3, w / 2);
		rect(w * 0.2, w / 4, w * 0.3, w / 2);
	} else if (type == 13) {
		for (let i = 0; i < 4; i++) {
			arc(-w * 0.5, -w * 0.5, w * 0.5, w * 0.5, 0, PI / 2);
			rotate(PI / 2);
		}
	} else if (type == 14) {
		arc(-w * 0.5, -w * 0.5, w, w, 0, PI / 2);
		arc(w * 0.5, -w * 0.5, w, w, PI / 2, PI);

	}
	pop();
}

function drawRoof(x, y, w) {
	let type = int(random(5));
	let clr1 = random(colors);
	let clr2 = random(colors);
	while (clr1 == clr2) {
		clr1 = random(colors);
		clr2 = random(colors);
	}
	push();
	translate(x, y);
	fill(clr1);
	if (type == 0) {
		arc(0, w / 2, w, w, PI, TAU, PIE);
		circle(0, - w * 0.25, w * 0.5);
	} else if (type == 1) {
		beginShape();
		vertex(- w / 2, w / 2);
		vertex(w / 2, w / 2);
		vertex(0, - (w / 2) + w * 0.1);
		endShape(CLOSE);
		circle(0, - w / 2, w * 0.2);
	} else if (type == 2) {
		beginShape();
		vertex(- w / 2, w / 2);
		vertex(w / 2, w / 2);
		vertex(0, 0);
		endShape(CLOSE);
		beginShape();
		vertex(0, 0);
		vertex(w / 4, -w / 4);
		vertex(0, -w / 2);
		vertex(-w / 4, -w / 4);
		endShape(CLOSE);
	} else if (type == 3) {
		beginShape();
		vertex(- w / 2, w / 2);
		vertex(w / 2, w / 2);
		vertex(0, -w * 1.5);
		endShape(CLOSE);
	} else if (type == 4) {
		beginShape();
		for (let a = 0; a < PI / 2; a += TAU / 180) {
			vertex(-w / 2 + w * 0.5 * cos(a), -w / 2 + w * sin(a));
		}
		for (let a = PI / 2; a < PI; a += TAU / 180) {
			vertex(w / 2 + w * 0.5 * cos(a), -w / 2 + w * sin(a));
		}
		endShape();
	} else if (type == 5) {

	}
	pop();
}

